import type { SidebarsConfig } from "@docusaurus/plugin-content-docs";
import { existsSync } from "node:fs";
import { createRequire } from "node:module";
import { join } from "node:path";

import { docsPath } from "./tissuumaps-docs";

// This runs in Node.js - Don't use client-side code here (browser APIs, JSX...)

/**
 * Creates the sidebars of the current version, which `docusaurus docs:version`
 * also saves for every released version (see scripts/prepare.ts)
 *
 * @param docsPath - The docs folder, with the API docs generated by typedoc
 * @returns The sidebars
 */
function createSidebars(docsPath: string): SidebarsConfig {
  const typedocSidebarFile = join(docsPath, "api", "typedoc-sidebar.cjs");
  if (!existsSync(typedocSidebarFile)) {
    throw new Error(
      `${typedocSidebarFile} not found, generate the API docs in TissUUmaps first`,
    );
  }
  const require = createRequire(import.meta.url);
  return {
    // By default, Docusaurus generates a sidebar from the docs folder structure
    docsSidebar: [{ type: "autogenerated", dirName: "." }],

    // The API reference has its own sidebar, generated by typedoc
    apiSidebar: [
      {
        type: "category",
        label: "API",
        link: { type: "doc", id: "api/index" },
        items: require(typedocSidebarFile) as Extract<
          SidebarsConfig[string],
          unknown[]
        >,
      },
    ],
  };
}

const sidebars: SidebarsConfig = docsPath ? createSidebars(docsPath) : {};

export default sidebars;
